#!/usr/bin/env python3
"""Authoring source for the bilingual campaign. Generated JSON is shipped and editable."""
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
RES=ROOT/'src/main/resources'
langs={k:json.loads((RES/f'assets/cobblemonworld/lang/{k}.json').read_text()) for k in ('vi_vn','en_us')}
world=dict(campaign=[],chains=[],scenes=[],teams=[],actors=[],pois=[],seasons=[])
def tr(key,vi,en):
 for k,t in [('vi_vn',vi),('en_us',en)]:langs[k][key]=t
 return key
actors={}
def actor(id,name,skin='professor_hale',team=''):
 if id not in actors:
  actors[id]=dict(id=id,name=name,skin=skin,team=team);world['actors'].append(actors[id])
 return id
# Existing named cast and the towns' supporting cast share authored appearance archetypes.
for p in (RES/'data/cobblemonworld/npcs').glob('*.json'):
 d=json.loads(p.read_text())
 if d['id']!='resonance_heart':actor(d['id'],d['displayName'],d.get('skin') or 'professor_hale',d['id'] if d.get('team') else '')
for row in [
 ('town1_lan','Cô Lan','daycare_mira'),('town1_bao','Bảo','mara_voss'),('town1_minh','Minh','mara_voss'),('town1_uncle_phuc','Bác Phúc','professor_hale'),
 ('town2_librarian_an','An','dr_orin'),('town2_student_linh','Linh','fashion_elle'),('town3_courier_nam','Nam','bicycle_tomo'),('town3_shady_trader','Đạt “Uy Tín”','rook'),('town3_victim_mai','Mai','fashion_elle'),
 ('town4_keeper_yen','Yến','selene_kade'),('town4_referee_tuan','Tuấn','battle_tower_receptionist'),('town5_ranger_hanh','Hạnh','sixth_warden'),
 ('town6_informant_duc','Đức','rocket_grunt_01'),('town6_mechanic_son','Sơn','bicycle_tomo'),('town7_curator_huong','Hương','archaeologist_marlow'),
 ('town8_dockworker_binh','Bình','captain_dorian'),('town8_fisher_thao','Thảo','daycare_mira'),('town8_trainer_hai','Hải','captain_dorian'),
 ('archive_keeper','Quản thủ Ánh','royal_league_receptionist'),('weather_researcher_mai','Tiến sĩ Mai','lab_scientist_iris'),('weather_guardian_groudon','Vệ binh Địa tầng Khoa','sixth_warden'),('weather_guardian_kyogre','Vệ binh Hải triều Nhi','seventh_warden'),
 ('town1_baker_quynh','Quỳnh','fashion_elle'),('town2_doctor_kim','Kim','daycare_mira'),('town3_accountant_tram','Trâm','royal_league_receptionist'),
 ('town4_gardener_luc','Lực','professor_hale'),('town5_firewatch_vu','Vũ','sixth_warden'),('town6_guard_chau','Châu','school_wolf_gatekeeper'),
 ('town7_photographer_ly','Ly','selene_kade'),('town8_captain_hoa','Hoa','harbour_marshal_liora')]:actor(*row)

def poi(id,vi,en,block='minecraft:lectern'):
 if not any(p['id']==id for p in world['pois']):world['pois'].append(dict(id=id,name=tr('narrative.point.'+id,vi,en),block=block))
 return id
personas={
'professor_hale':('Ta muốn cậu về nhà nguyên vẹn. Có gì không ổn thì gọi ta, đừng tự ôm hết.','I want you home in one piece. Call me if something is wrong; you do not have to carry it alone.'),
'mara_voss':('Cậu lo phần của cậu. Tôi lo phần của tôi. Và đừng có biến mất giữa chừng.','You handle your part. I will handle mine. And do not disappear halfway through.'),
'dr_orin':('Được. Bản ngắn: chúng ta cần bằng chứng trước khi kết luận. Tôi sẽ giữ bản dài cho Hale.','All right. Short version: evidence first, conclusions second. Hale can have the long version.'),
'rook':('Tôi chỉ sắp xếp một cuộc trao đổi dân sự. Phần phiền phức, đáng tiếc, thuộc về cậu.','I am arranging a civil exchange. Unfortunately, the inconvenient part is yours.'),
'selene_kade':('Đừng tin tôi vì tôi nói hay. Kiểm tra điều tôi vừa nói.','Do not trust me because I sound convincing. Check what I told you.'),
'lab_scientist_iris':('Tôi đã ký những báo cáo sai. Giúp cậu không xóa được việc đó. Nhưng tôi có thể ngừng làm sai.','I signed false reports. Helping you will not erase that. But I can stop making it worse.'),
'aurelia':('Một chức danh không miễn cho ai trách nhiệm. Kể cả tôi.','A title does not excuse anyone from responsibility. Me included.'),
'school_wolf_master':('Hỏi thì được. Lười suy nghĩ thì không.','Questions are allowed. Refusing to think is not.'),
'mysterious':('Giữ câu hỏi đó. Lần này, cậu sẽ có cơ hội kiểm chứng lời tôi.','Keep that question. This time, you will get to test my answer.')}

def scene(id,speaker,vi,en,after_vi,after_en,choices=None):
 actor_name=actors.get(speaker,{}).get('name',speaker)
 root='narrative.scene.'+id
 key=tr(root+'.line',vi,en);facts=tr(root+'.facts',after_vi,after_en)
 defaults=[('serious','Nói rõ phần tôi cần làm.','Tell me what you need me to do.','Được. Ta nói từng việc, rồi cậu quyết định.','All right. One thing at a time, then you decide.'),
 ('sarcastic','Tôi có nên lo từ bây giờ không?','Should I start worrying now?','Lo vừa đủ để nhìn đường. Đừng lo đến mức đứng yên.','Enough to watch your step. Not enough to stop moving.'),
 ('greedy','Vụ này có thưởng không?','Is there a reward for this?','Việc trước mắt không đổi chỉ vì cậu hỏi tiền. Nhiệm vụ phụ có thưởng rõ ràng.','The task does not change when you ask about money. Side jobs have a stated reward.'),
 ('polite','Tôi nghe đây.','I am listening.',*personas.get(speaker,('Cảm ơn. Cứ hỏi nếu có chỗ nào chưa rõ.','Thank you. Ask if anything is unclear.')))]
 if choices is not None:defaults=choices
 options=[];nodes=[]
 for i,(trait,qv,qe,rv,re) in enumerate(defaults):
  reply=tr(root+f'.reply{i}',rv,re)
  options.append(dict(id=f'answer{i}',text=tr(root+f'.choice{i}',qv,qe),reply='',next=f'response{i}',personality=trait,action=''))
  nodes.append(dict(id=f'response{i}',speaker=speaker,text=reply,choices=[dict(id='continue',text=tr('narrative.cobblemonworld.continue','Tiếp tục','Continue'),reply='',next='facts',personality='',action='')]))
 nodes.insert(0,dict(id='start',speaker=speaker,text=key,choices=options))
 nodes.append(dict(id='facts',speaker=speaker,text=facts,choices=[dict(id='finish',text=tr('narrative.cobblemonworld.ready','Được. Tôi làm đây.','All right. I am ready.'),reply='',next='',personality='',action='finish')]))
 world['scenes'].append(dict(id=id,start='start',nodes=nodes))
 return id

def stage(id,act,chapter,kind,target,titlevi,titleen,objvi,objen,linevi,lineen,aftervi,afteren,flags=(),legacy='',item='',amount=1,choices=None):
 speaker=target if target in actors else {'rocket_terminal':'lab_scientist_iris'}.get(target,'archive_keeper')
 if kind=='inspect' and target not in actors:poi(target,titlevi,titleen)
 sid=scene(id,speaker,linevi,lineen,aftervi,afteren,choices)
 return dict(id=id,act=act,chapter=chapter,title=tr('narrative.stage.'+id+'.title',titlevi,titleen),objective=tr('narrative.stage.'+id+'.objective',objvi,objen),type=kind,target=target,item=item,amount=amount,scene=sid,flags=list(flags),legacyFlag=legacy)
def main(*args,**kw):world['campaign'].append(stage(*args,**kw))
# Act 0: the town is introduced through actual services, a local errand and a rival.
main('arrival','0','first_challenge','travel','professor_hale','Về thị trấn','Arrival','Tới phòng nghiên cứu của Giáo sư Hale.','Visit Professor Hale’s research room.','Cửa phòng nghiên cứu vẫn mở. Hale đã để phần bàn gần cửa cho cậu.','The research room is open. Hale has cleared the desk by the door.','Chưa ai cần cậu cứu thế giới hôm nay. Cứ vào chào ông ấy trước.','Nobody needs you to save the world today. Go say hello first.')
main('hale_phone','0','first_challenge','talk','professor_hale','Một số điện thoại','A number to call','Nói với Hale về chuyến đi và nhận hướng dẫn dùng điện thoại.','Talk to Hale about the journey and your Trainer Phone.','Đừng thức đến ba giờ sáng rồi bảo Pokémon thiếu năng lượng. Điện thoại này để cậu gọi người giúp, không phải để thức thêm.','Do not stay up until three and blame your Pokémon for being tired. The phone is for calling for help, not staying up later.','Mira chăm Pokémon ở gần đây. Ren bán đồ đi đường. Mara đang chờ một trận nghiêm túc. Nhưng trước hết, ta có việc nhỏ cho cậu.','Mira looks after Pokémon nearby. Ren sells travel supplies. Mara wants a proper battle. First, I have a small errand.',flags=['professor_met','prologue_complete','divinos_journey_started','trainer_phone_obtained'])
main('mira_visit','0','first_challenge','heal','daycare_mira','Trước khi lên đường','Before the road','Nhờ Mira kiểm tra và chữa party Pokémon.','Ask Mira to check and heal your Pokémon party.','Mang cả đội lại đây. Không ai cần cố tỏ ra ổn khi đang bị thương.','Bring the whole team over. Nobody has to pretend they are fine while hurt.','Mira chữa cả party. Cậu có thể quay lại bất cứ lúc nào ngoài trận đấu.','Mira heals the entire party. You can return whenever you are out of battle.',flags=['daycare_known'])
main('ren_supplies','0','first_challenge','buy','pokemall_ren','Đồ cho buổi đầu','First-day supplies','Mua một gói vật phẩm ở shop của Ren.','Buy a supply bundle from Ren’s shop.','Có giảm giá không? Có. Không giảm. Tôi trả lời đủ hai câu cho nhanh.','Discount? Yes. The discount is zero. There, saved us both a question.','Chọn gói phù hợp rồi mua trong shop. Giá và BeastCoin đều hiện trên quầy. Nếu thiếu tiền, quay lại sau một nhiệm vụ phụ.','Choose a bundle in the shop. The price and BeastCoin balance are on the counter. Short on money? A side job can help.',flags=['pokemall_known'])
main('lan_errand','0','first_challenge','talk','town1_lan','Cái giỏ bỏ quên','The forgotten basket','Hỏi cô Lan cần gửi gì cho Hale.','Ask Lan what Hale forgot.','Ông Hale để quên bữa trưa. Lần thứ ba tuần này. Đừng kể với ông là cô đếm.','Hale forgot his lunch. Third time this week. Do not tell him I am counting.','Mang ba quả táo cho ông ấy. Khoa học không thay được bữa trưa. Còn Mara đã hỏi cậu hai lần rồi.','Take him three apples. Science is not a substitute for lunch. Mara has asked about you twice.')
main('hale_lunch','0','first_challenge','deliver','professor_hale','Khoa học cần ăn trưa','Science needs lunch','Giao 3 quả táo cho Hale.','Deliver 3 apples to Hale.','Lan nhờ à? Ta chỉ định đọc thêm một trang. Rồi thêm một trang nữa.','Lan sent you? I meant to read one more page. Then another.','Cảm ơn. Mara ở sân tập. Cậu không cần thắng để bắt đầu hành trình, nhưng phải hiểu đội của mình.','Thank you. Mara is at the practice field. You do not have to win to begin, but you need to understand your team.',item='minecraft:apple',amount=3)
main('mara_intro','0','first_challenge','talk','mara_voss','Đối thủ cùng đường','A rival on the same road','Gặp Mara ở sân tập.','Meet Mara at the practice field.','Tưởng cậu chạy mất rồi. Tôi không chờ cả buổi chỉ để xem cậu chọn màu vỏ điện thoại.','I thought you had run away. I did not wait all morning to watch you choose a phone case.','Tôi đánh để biết mình còn thiếu gì. Cậu cũng nên thế. Chuẩn bị đội rồi quay lại.','I battle to find out what I am missing. You should too. Prepare your team and come back.')
main('mara_first','0','first_challenge','battle','mara_voss','Thử thách đầu tiên','The First Challenge','Thắng trận thử thách đầu tiên với Mara.','Win your first proper challenge against Mara.','Khoan. Đứng im. Tôi cần xem lại khoảng 36 tín hiệu VAR trước khi cậu làm cái mặt đấy.','Hold on. Stand still. I need about thirty-six VAR angles before you make that face.','Không có trọng tài cứu cậu đâu. Chúng ta đánh công bằng. Thua thì chữa đội rồi rematch, không mất tiến trình.','No referee is saving you. We battle fairly. If you lose, heal and rematch; your progress stays safe.',legacy='mara_voss_defeated',choices=[('sarcastic','Đây là Pokémon hay Premier League?','Is this Pokémon or the Premier League?','Chính câu đấy làm tôi muốn kiểm tra thêm.','That answer makes me want another replay.'),('serious','Đội tôi sẵn sàng rồi.','My team is ready.','Tốt. Nói bằng trận đấu.','Good. Let the battle speak.'),('chaotic','VAR gì? Tôi ra đòn trước mà.','VAR? I attacked first.','Ừ, và tôi nhớ chuyện đó rất rõ.','Yes. I remember that part very clearly.'),('polite','Đánh xong tôi nghe cô phân tích.','I will listen to your analysis afterward.','Cậu tự nguyện đấy nhé.','You volunteered. Remember that.')])
main('field_fault','0','first_challenge','inspect','practice_log','Một giây bị mất','The missing second','Kiểm tra nhật ký tại sân tập sau trận Mara.','Inspect the practice-field log after the battle.','Nhật ký ghi hai lần kết thúc trận cách nhau một giây. Camera chỉ có một. Không phải lỗi của Pokémon.','The log records two battle endings a second apart. The camera has only one. The Pokémon did nothing wrong.','Có một tài khoản cũ xác nhận kết quả trước khi trận kết thúc. Mã định danh bị che, nhưng ngày tạo sớm hơn cả sân tập.','An old account confirmed the result before the battle ended. Its name is hidden, but the account predates the field.',flags=['first_record_fault'])
main('hale_fault','0','first_challenge','talk','professor_hale','Điều ông không nói','What he will not say','Đưa phát hiện ở sân tập cho Hale.','Tell Hale what the practice log showed.','Ta từng thấy định dạng này. Không, nó không phải thứ cậu cần đuổi theo một mình.','I have seen this format before. No, it is not something you should chase alone.','Orin giữ bản sao hồ sơ cũ ở thị trấn thứ hai. Mang câu hỏi này cho ông ấy. Nếu có người lạ nhắn, đừng đưa vị trí của cậu.','Orin keeps copies of the old records in the second town. Ask him. If a stranger messages you, do not share your location.',flags=['orin_referral'])
main('unknown_first','0','first_challenge','talk','town1_uncle_phuc','Tin nhắn từ người lạ','A message from nobody','Gặp bác Phúc để kiểm tra chiếc hộp thư bị bỏ lại ở sân tập.','Ask Phuc about the abandoned practice-field mailbox.','Có người nhờ tôi đưa cái này. Không tên, không mặt. Cậu nghĩ tôi không hỏi à? Tôi hỏi. Nó bảo “Hale sẽ hiểu”.','Someone asked me to hand this over. No name, no face. Of course I asked. They said, “Hale will understand.”','Tin nhắn: “Đừng sửa nhật ký. Giữ bản gốc. Lần trước họ đã sửa cả tên người thắng.” Người gửi hiển thị ???. Mara cũng phải xem bản này.','The message reads: “Do not repair the log. Keep the original. Last time, they changed the winner’s name too.” Sender: ???. Mara needs to see this.',flags=['unknown_contact_received'])
main('mara_aftermath','0','first_challenge','talk','mara_voss','Không đi một mình','Do not go alone','Cho Mara xem tin nhắn lạ trước khi sang thị trấn thứ hai.','Show Mara the strange message before leaving for town two.','Cậu thắng tôi, không có nghĩa cậu giỏi nhận biết lừa đảo. Đừng trả lời địa chỉ nhà cho cái số ba dấu hỏi kia.','Beating me does not make you good at spotting scams. Do not send your home address to three question marks.','Tôi giữ một bản nhật ký. Cậu đi gặp Orin. Nếu hai bản khác nhau, ta sẽ biết có người sửa nó. Còn trận sau tôi sẽ thắng.','I will keep a copy of the log. You go see Orin. If the copies change, we will know someone edited them. And I am winning the next battle.',flags=['act0_complete'])
