first=next(s for s in world['scenes'] if s['id']=='orin_summary')
longvi=' Trước hết, một bản ghi có ba phần: người gửi, lệnh đã nhận, và thời điểm máy xác nhận. Nếu chỉ thời điểm sai, ta kiểm tra đồng hồ. Nếu tên sai trong cả bản sao độc lập, ta kiểm tra đường chuyển dữ liệu. Nhưng ở đây có một dấu sửa giống nhau trong hai kho mà lịch lưu không trùng. Nghĩa là người sửa đã biết kho nào sẽ được đem đối chiếu. Hale tin giữ kín hồ sơ sẽ ngăn người khác dùng lại hệ thống. Tôi đã phản đối, nhưng tôi cũng không gửi bản sao ra ngoài. Cậu thấy vấn đề chưa? Hai người tranh luận rất lâu vẫn có thể cùng không làm việc cần làm. Tôi không kể điều này để cậu chọn giáo sư tốt hơn. Tôi kể để cậu đòi chứng cứ từ cả hai. Bây giờ nhìn giấy dưới tay cậu: chữ ký ở sân tập và thư viện khớp. Đó là phần kiểm chứng được. Phần còn lại là câu hỏi, không phải kết luận.'
longen=' A record has three parts: the sender, the received instruction, and the acknowledgment time. A wrong timestamp asks us to check the clock. A wrong name in independent copies asks us to check the transfer path. Here, identical edits appear in two archives with different backup schedules. The editor knew which copies would be compared. Hale believed secrecy would prevent the system being reused. I objected, but I did not send a copy outside either. Two people can debate for years and both fail to do what mattered. I am not asking you to choose the better professor. I am asking you to demand evidence from both. Look at the sheet: the practice-field and library signatures match. That part is testable. Everything else remains a question, not a conclusion.'
linekey=first['nodes'][0]['text'];langs['vi_vn'][linekey]+=longvi;langs['en_us'][linekey]+=longen
first['nodes'][0]['choices'][0]['text']=tr('narrative.orin.short','Thông não chi thuật bản rút gọn được không?','Could you use the ten-second explanation?')
replykey=next(n for n in first['nodes'] if n['id']=='response0')['text'];tr(replykey,'...Được. Có người sửa hồ sơ. Rook có thẻ vào kho. Kiểm tra thẻ trước khi tin ông ta.','...All right. Someone edited the records. Rook has depot access. Check the card before trusting him.')
